UPDATE recommendation_library SET code = 'rec-emyth' WHERE title = 'The E-Myth Revisited' AND code IS NULL;

INSERT INTO recommendation_library (type, title, author_or_name, description, is_active, sort_order, code, review_status) VALUES
  ('BUKU', 'The E-Myth Revisited', 'Michael E. Gerber', 'Bekerja pada bisnis, bukan hanya di dalam bisnis. Bacaan ini menjelaskan mengapa owner yang mengerjakan semuanya sendiri tidak otomatis punya perusahaan.', true, 1, 'rec-emyth', 'published'),
  ('TOOL', 'Cara menandai Tidak Berlaku', NULL, 'Lembar kerja untuk memisahkan butir yang memang di luar model bisnis dari butir yang belum dikerjakan lalu dijawab Tidak Berlaku. Bukan produk berbayar.', true, 2, 'rec-baca-ulang', 'draft'),
  ('TOOL', 'Peta operasi yang bisa diulang', NULL, 'Urutkan pemasok, stok, jadwal, dan mutu sampai order kedua tidak bergantung pada ingatan owner.', true, 3, 'rec-operasi-dasar', 'draft'),
  ('TOOL', 'Harga dan cara mencari pembeli', NULL, 'Tulis satu penawaran yang sudah pernah laku dua kali, beserta cara mencari pembeli yang bisa diulang.', true, 4, 'rec-penjualan-dasar', 'draft'),
  ('TOOL', 'Margin per produk', NULL, 'Pisahkan produk yang ramai dari produk yang benar-benar menyisakan uang setelah HPP dan biaya tetap.', true, 5, 'rec-unit-economics', 'draft'),
  ('TOOL', 'Mesin penjualan tanpa satu figur', NULL, 'Tulis funnel, pemilik kanal, dan apa yang tetap jalan bila satu orang cuti.', true, 6, 'rec-mesin-penjualan', 'draft'),
  ('TOOL', 'Laba rugi satu halaman', NULL, 'Satu halaman bulanan: penjualan, HPP, biaya, sisa. Diisi dari buku kas, bukan dari ingatan.', true, 7, 'rec-laba-rugi', 'draft'),
  ('TOOL', 'Batas kas dan cadangan', NULL, 'Tetapkan kas minimum operasional dan cadangan beberapa bulan sebelum uang pertumbuhan dipakai untuk belanja baru.', true, 8, 'rec-kas-cadangan', 'draft'),
  ('TOOL', 'Dasbor kas 13 minggu', NULL, 'Lima angka mingguan ditambah prakiraan 13 minggu, dengan satu orang yang memperbaruinya pada hari yang sama.', true, 9, 'rec-dashboard-kas', 'draft'),
  ('TOOL', 'Uji ketahanan sebelum melompat', NULL, 'Ekspansi hanya dari kas yang terpisah dari kas harian. Kalau cadangan operasional tersentuh, lompatan ditunda.', true, 10, 'rec-modal-ekspansi', 'draft'),
  ('TOOL', 'Pengingat rezim pajak', NULL, 'Catat bentuk usaha dan ambang yang membuat satu rezim berlaku atau tidak. Angka di instrumen adalah pengingat, bukan nasihat pajak.', true, 11, 'rec-pajak-rezim', 'draft'),
  ('TOOL', 'Perjanjian dan upah', NULL, 'Daftar siapa yang bekerja, statusnya, dan upah yang dibayar dari rekening usaha. Konfirmasi ke penasihat sebelum menyalin angka.', true, 12, 'rec-hubungan-kerja', 'draft'),
  ('TOOL', 'Daftar periksa uji tuntas', NULL, 'Hukum, pajak, dan operasi dicek sebelum akuisisi, kemitraan, atau wilayah baru ditandatangani.', true, 13, 'rec-uji-tuntas', 'draft'),
  ('TOOL', 'Pajak badan yang tersistem', NULL, 'Rekonsiliasi fiskal dan angsuran tidak lagi diurus dari ingatan. Selisih dianggarkan, bukan ditunda.', true, 14, 'rec-coretax', 'draft'),
  ('TOOL', 'Orang pertama yang nyata', NULL, 'Pilih, tugaskan, dan bayar satu peran sampai pekerjaan itu lepas dari tangan owner.', true, 15, 'rec-sdm-dasar', 'draft'),
  ('TOOL', 'Keputusan yang selesai', NULL, 'Satu keputusan yang sudah menggantung ditulis, diberi tanggal, dan tidak diubah besoknya.', true, 16, 'rec-kepemimpinan-awal', 'draft'),
  ('TOOL', 'SOP satu proses inti', NULL, 'Tulis satu proses yang masih menempel di owner, lalu biarkan orang lain menjalankannya dua minggu.', true, 17, 'rec-sop', 'draft'),
  ('TOOL', 'Matriks wewenang', NULL, 'Keputusan, pemangku, dan batas nilainya tertulis sehingga eskalasi ke owner hanya untuk yang memang di luar batas.', true, 18, 'rec-tata-kelola', 'draft'),
  ('TOOL', 'Pangkas persetujuan yang tidak menambah nilai', NULL, 'Hitung lapisan tanda tangan pada satu keputusan rutin, lalu hapus yang tidak mengubah risiko.', true, 19, 'rec-lean-birokrasi', 'draft'),
  ('TOOL', 'Satu angka yang dipercaya', NULL, 'Penjualan, stok, dan kas punya satu sumber. Rekonsiliasi mingguan sampai selisihnya dijelaskan.', true, 20, 'rec-integrasi-sistem', 'draft'),
  ('TOOL', 'Perbaikan tanpa menunggu owner', NULL, 'Satu kebiasaan perbaikan yang jalan tanpa owner punya ide baru setiap Senin.', true, 21, 'rec-budaya', 'draft'),
  ('TOOL', 'Calon untuk posisi kunci', NULL, 'Setiap posisi kunci, termasuk peran owner, punya minimal satu calon dan tugas nyata kuartal ini.', true, 22, 'rec-kader', 'draft'),
  ('TOOL', 'Janji yang ditutup', NULL, 'Daftar janji yang belum ditepati, selesaikan atau beritahu ulang, dan jangan buka penawaran baru sebelum yang lama tertutup.', true, 23, 'rec-amanah', 'draft'),
  ('TOOL', 'Proses inti tanpa owner sebulan', NULL, 'Uji satu proses inti berjalan penuh tanpa owner, bukan hanya saat owner libur sehari.', true, 24, 'rec-sistem-matang', 'draft'),
  ('TOOL', 'Playbook dari unit yang sehat', NULL, 'Tulis cara unit yang paling sehat melayani pelanggan, uji di satu tempat lain, baru gandakan.', true, 25, 'rec-playbook-ekspansi', 'draft'),
  ('TOOL', 'Identitas yang tertulis', NULL, 'Nilai yang tidak boleh ditukar dengan pertumbuhan ditulis, lalu satu keputusan ekspansi dicek terhadap teks itu.', true, 26, 'rec-identitas', 'draft'),
  ('TOOL', 'Rekening dan buku yang terpisah', NULL, 'Belanja usaha keluar dari rekening usaha, dan buku kas usaha tidak mencampur mutasi rumah.', true, 27, 'rec-pisah-uang', 'draft'),
  ('TOOL', 'Harga dari HPP', NULL, 'Bahan, tenaga, dan ongkos langsung dihitung sebelum harga jual dipertahankan karena kebiasaan.', true, 28, 'rec-hpp', 'draft'),
  ('TOOL', 'Titik impas bulanan', NULL, 'Biaya tetap dibagi selisih harga dan HPP. Itu jumlah minimal sebelum usaha berhenti menanggung biaya.', true, 29, 'rec-bep', 'draft'),
  ('TOOL', 'Satu peran yang lepas', NULL, 'Satu pekerjaan berulang diajarkan, dikerjakan orang lain dua minggu, dan tidak diambil kembali.', true, 30, 'rec-delegasi', 'draft')
ON CONFLICT (code) DO UPDATE SET type = EXCLUDED.type, title = EXCLUDED.title, author_or_name = EXCLUDED.author_or_name, description = EXCLUDED.description, is_active = true, sort_order = EXCLUDED.sort_order, review_status = EXCLUDED.review_status;

INSERT INTO section_education (audit_code, section_code, measures, why_it_matters, concepts, framework, common_mistakes, strength_reading, gap_reading, review_status) VALUES
  ('audit_1_2', 'A', 'Operasi Survival diukur dari kemampuan mengulang pesanan: pemasok tetap, stok yang tidak mengejutkan, jadwal yang tidak bergantung pada ingatan, dan mutu yang sama pada order kedua.', 'Seksi A Produksi / Operasi ikut menentukan apakah transisi ini ditopang praktik harian, bukan hanya niat owner.', 'Operasi Survival diukur dari kemampuan mengulang pesanan: pemasok tetap, stok yang tidak mengejutkan, jadwal yang tidak bergantung pada ingatan, dan mutu yang sama pada order kedua. Butir bintang di seksi ini adalah gerbang. Skor butir biasa tidak menutup butir bintang yang dijawab Tidak.', 'Baca seksi Produksi / Operasi dalam dua lapis. Butir yang dijawab Tidak Berlaku keluar dari pembilang dan penyebut. Butir tanpa panduan peserta memakai narasi seksi ini sebagai pengganti.', 'Kesalahan yang sering muncul di Produksi / Operasi: menjawab Ya karena pernah dilakukan sekali, atau menandai Tidak Berlaku untuk kondisi yang sebenarnya masih berlaku.', 'Jawaban Ya di Produksi / Operasi berarti praktik ini sudah terlihat pada kerja minggu ini, bukan hanya ada di rencana.', 'Jawaban Tidak di Produksi / Operasi menjadi urutan kerja. Bila butirnya tidak punya panduan untuk peserta, gunakan narasi seksi ini.', 'draft'),
  ('audit_1_2', 'B', 'Penjualan fase ini bukan soal ramai. Harga harus lahir dari HPP, ada cara mencari pembeli yang bisa diulang, dan layanan tidak berhenti saat owner sedang produksi.', 'Seksi B Sales & Marketing ikut menentukan apakah transisi ini ditopang praktik harian, bukan hanya niat owner.', 'Penjualan fase ini bukan soal ramai. Harga harus lahir dari HPP, ada cara mencari pembeli yang bisa diulang, dan layanan tidak berhenti saat owner sedang produksi. Butir bintang di seksi ini adalah gerbang. Skor butir biasa tidak menutup butir bintang yang dijawab Tidak.', 'Baca seksi Sales & Marketing dalam dua lapis. Butir yang dijawab Tidak Berlaku keluar dari pembilang dan penyebut. Butir tanpa panduan peserta memakai narasi seksi ini sebagai pengganti.', 'Kesalahan yang sering muncul di Sales & Marketing: menjawab Ya karena pernah dilakukan sekali, atau menandai Tidak Berlaku untuk kondisi yang sebenarnya masih berlaku.', 'Jawaban Ya di Sales & Marketing berarti praktik ini sudah terlihat pada kerja minggu ini, bukan hanya ada di rencana.', 'Jawaban Tidak di Sales & Marketing menjadi urutan kerja. Bila butirnya tidak punya panduan untuk peserta, gunakan narasi seksi ini.', 'draft'),
  ('audit_1_2', 'C', 'Keuangan Survival adalah matematika bertahan: uang terpisah, model yang berulang, titik impas, rekening usaha, dan laba rugi bulanan yang bisa ditunjukkan.', 'Seksi C Keuangan & Akuntansi ikut menentukan apakah transisi ini ditopang praktik harian, bukan hanya niat owner.', 'Keuangan Survival adalah matematika bertahan: uang terpisah, model yang berulang, titik impas, rekening usaha, dan laba rugi bulanan yang bisa ditunjukkan. Butir bintang di seksi ini adalah gerbang. Skor butir biasa tidak menutup butir bintang yang dijawab Tidak.', 'Baca seksi Keuangan & Akuntansi dalam dua lapis. Butir yang dijawab Tidak Berlaku keluar dari pembilang dan penyebut. Butir tanpa panduan peserta memakai narasi seksi ini sebagai pengganti.', 'Kesalahan yang sering muncul di Keuangan & Akuntansi: menjawab Ya karena pernah dilakukan sekali, atau menandai Tidak Berlaku untuk kondisi yang sebenarnya masih berlaku.', 'Jawaban Ya di Keuangan & Akuntansi berarti praktik ini sudah terlihat pada kerja minggu ini, bukan hanya ada di rencana.', 'Jawaban Tidak di Keuangan & Akuntansi menjadi urutan kerja. Bila butirnya tidak punya panduan untuk peserta, gunakan narasi seksi ini.', 'draft'),
  ('audit_1_2', 'D', 'Kepatuhan di fase ini sengaja ringan: pajak UMKM bila syaratnya berlaku, serta BPJS dan upah begitu ada orang pertama. Ini bukan nasihat hukum.', 'Seksi D Kepatuhan Dasar — Pajak, Legal, BPJS (2026, Bertahap) ikut menentukan apakah transisi ini ditopang praktik harian, bukan hanya niat owner.', 'Kepatuhan di fase ini sengaja ringan: pajak UMKM bila syaratnya berlaku, serta BPJS dan upah begitu ada orang pertama. Ini bukan nasihat hukum. Butir bintang di seksi ini adalah gerbang. Skor butir biasa tidak menutup butir bintang yang dijawab Tidak.', 'Baca seksi Kepatuhan Dasar — Pajak, Legal, BPJS (2026, Bertahap) dalam dua lapis. Butir yang dijawab Tidak Berlaku keluar dari pembilang dan penyebut. Butir tanpa panduan peserta memakai narasi seksi ini sebagai pengganti.', 'Kesalahan yang sering muncul di Kepatuhan Dasar — Pajak, Legal, BPJS (2026, Bertahap): menjawab Ya karena pernah dilakukan sekali, atau menandai Tidak Berlaku untuk kondisi yang sebenarnya masih berlaku.', 'Jawaban Ya di Kepatuhan Dasar — Pajak, Legal, BPJS (2026, Bertahap) berarti praktik ini sudah terlihat pada kerja minggu ini, bukan hanya ada di rencana.', 'Jawaban Tidak di Kepatuhan Dasar — Pajak, Legal, BPJS (2026, Bertahap) menjadi urutan kerja. Bila butirnya tidak punya panduan untuk peserta, gunakan narasi seksi ini.', 'draft'),
  ('audit_1_2', 'E', 'SDM pertama bukan soal struktur perusahaan. Yang diukur adalah cara memilih, menugaskan, dan membayar orang sehingga owner tidak lagi memegang semua pekerjaan.', 'Seksi E Sumber Daya Manusia ikut menentukan apakah transisi ini ditopang praktik harian, bukan hanya niat owner.', 'SDM pertama bukan soal struktur perusahaan. Yang diukur adalah cara memilih, menugaskan, dan membayar orang sehingga owner tidak lagi memegang semua pekerjaan. Butir bintang di seksi ini adalah gerbang. Skor butir biasa tidak menutup butir bintang yang dijawab Tidak.', 'Baca seksi Sumber Daya Manusia dalam dua lapis. Butir yang dijawab Tidak Berlaku keluar dari pembilang dan penyebut. Butir tanpa panduan peserta memakai narasi seksi ini sebagai pengganti.', 'Kesalahan yang sering muncul di Sumber Daya Manusia: menjawab Ya karena pernah dilakukan sekali, atau menandai Tidak Berlaku untuk kondisi yang sebenarnya masih berlaku.', 'Jawaban Ya di Sumber Daya Manusia berarti praktik ini sudah terlihat pada kerja minggu ini, bukan hanya ada di rencana.', 'Jawaban Tidak di Sumber Daya Manusia menjadi urutan kerja. Bila butirnya tidak punya panduan untuk peserta, gunakan narasi seksi ini.', 'draft'),
  ('audit_1_2', 'F', 'Manajemen di sini adalah keputusan owner: tegas, ada ritme mingguan, dan tanggung jawab tidak menguap saat ada masalah.', 'Seksi F Manajemen ikut menentukan apakah transisi ini ditopang praktik harian, bukan hanya niat owner.', 'Manajemen di sini adalah keputusan owner: tegas, ada ritme mingguan, dan tanggung jawab tidak menguap saat ada masalah. Butir bintang di seksi ini adalah gerbang. Skor butir biasa tidak menutup butir bintang yang dijawab Tidak.', 'Baca seksi Manajemen dalam dua lapis. Butir yang dijawab Tidak Berlaku keluar dari pembilang dan penyebut. Butir tanpa panduan peserta memakai narasi seksi ini sebagai pengganti.', 'Kesalahan yang sering muncul di Manajemen: menjawab Ya karena pernah dilakukan sekali, atau menandai Tidak Berlaku untuk kondisi yang sebenarnya masih berlaku.', 'Jawaban Ya di Manajemen berarti praktik ini sudah terlihat pada kerja minggu ini, bukan hanya ada di rencana.', 'Jawaban Tidak di Manajemen menjadi urutan kerja. Bila butirnya tidak punya panduan untuk peserta, gunakan narasi seksi ini.', 'draft'),
  ('audit_1_2', 'G', 'Riset dan budaya di fase awal adalah kebiasaan kecil: mencoba perbaikan, dan cara kerja yang tidak berubah-ubah tiap minggu.', 'Seksi G R&D & Budaya Kerja ikut menentukan apakah transisi ini ditopang praktik harian, bukan hanya niat owner.', 'Riset dan budaya di fase awal adalah kebiasaan kecil: mencoba perbaikan, dan cara kerja yang tidak berubah-ubah tiap minggu. Butir bintang di seksi ini adalah gerbang. Skor butir biasa tidak menutup butir bintang yang dijawab Tidak.', 'Baca seksi R&D & Budaya Kerja dalam dua lapis. Butir yang dijawab Tidak Berlaku keluar dari pembilang dan penyebut. Butir tanpa panduan peserta memakai narasi seksi ini sebagai pengganti.', 'Kesalahan yang sering muncul di R&D & Budaya Kerja: menjawab Ya karena pernah dilakukan sekali, atau menandai Tidak Berlaku untuk kondisi yang sebenarnya masih berlaku.', 'Jawaban Ya di R&D & Budaya Kerja berarti praktik ini sudah terlihat pada kerja minggu ini, bukan hanya ada di rencana.', 'Jawaban Tidak di R&D & Budaya Kerja menjadi urutan kerja. Bila butirnya tidak punya panduan untuk peserta, gunakan narasi seksi ini.', 'draft'),
  ('audit_1_2', 'H', 'Gerbang kepemimpinan: ada orang yang membantu, owner masih mau belajar, dan amanah tidak ditinggalkan saat order menumpuk.', 'Seksi H Kepemimpinan, SDM & Syariah ikut menentukan apakah transisi ini ditopang praktik harian, bukan hanya niat owner.', 'Gerbang kepemimpinan: ada orang yang membantu, owner masih mau belajar, dan amanah tidak ditinggalkan saat order menumpuk. Butir bintang di seksi ini adalah gerbang. Skor butir biasa tidak menutup butir bintang yang dijawab Tidak.', 'Baca seksi Kepemimpinan, SDM & Syariah dalam dua lapis. Butir yang dijawab Tidak Berlaku keluar dari pembilang dan penyebut. Butir tanpa panduan peserta memakai narasi seksi ini sebagai pengganti.', 'Kesalahan yang sering muncul di Kepemimpinan, SDM & Syariah: menjawab Ya karena pernah dilakukan sekali, atau menandai Tidak Berlaku untuk kondisi yang sebenarnya masih berlaku.', 'Jawaban Ya di Kepemimpinan, SDM & Syariah berarti praktik ini sudah terlihat pada kerja minggu ini, bukan hanya ada di rencana.', 'Jawaban Tidak di Kepemimpinan, SDM & Syariah menjadi urutan kerja. Bila butirnya tidak punya panduan untuk peserta, gunakan narasi seksi ini.', 'draft'),
  ('audit_2_3', 'A', 'Operasi fase tumbuh harus bisa dijalankan orang lain: pembelian, stok, jadwal, dan mutu tidak lagi menunggu owner menunjuk setiap langkah.', 'Seksi A Produksi / Operasi ikut menentukan apakah transisi ini ditopang praktik harian, bukan hanya niat owner.', 'Operasi fase tumbuh harus bisa dijalankan orang lain: pembelian, stok, jadwal, dan mutu tidak lagi menunggu owner menunjuk setiap langkah. Butir bintang di seksi ini adalah gerbang. Skor butir biasa tidak menutup butir bintang yang dijawab Tidak.', 'Baca seksi Produksi / Operasi dalam dua lapis. Butir yang dijawab Tidak Berlaku keluar dari pembilang dan penyebut. Butir tanpa panduan peserta memakai narasi seksi ini sebagai pengganti.', 'Kesalahan yang sering muncul di Produksi / Operasi: menjawab Ya karena pernah dilakukan sekali, atau menandai Tidak Berlaku untuk kondisi yang sebenarnya masih berlaku.', 'Jawaban Ya di Produksi / Operasi berarti praktik ini sudah terlihat pada kerja minggu ini, bukan hanya ada di rencana.', 'Jawaban Tidak di Produksi / Operasi menjadi urutan kerja. Bila butirnya tidak punya panduan untuk peserta, gunakan narasi seksi ini.', 'draft'),
  ('audit_2_3', 'B', 'Cari Duit artinya tahu produk yang paling menguntungkan, harga yang tidak harus owner yang menetapkan, dan target penjualan yang sebagian sudah lepas dari pundak owner.', 'Seksi B Marketing & Penjualan ikut menentukan apakah transisi ini ditopang praktik harian, bukan hanya niat owner.', 'Cari Duit artinya tahu produk yang paling menguntungkan, harga yang tidak harus owner yang menetapkan, dan target penjualan yang sebagian sudah lepas dari pundak owner. Butir bintang di seksi ini adalah gerbang. Skor butir biasa tidak menutup butir bintang yang dijawab Tidak.', 'Baca seksi Marketing & Penjualan dalam dua lapis. Butir yang dijawab Tidak Berlaku keluar dari pembilang dan penyebut. Butir tanpa panduan peserta memakai narasi seksi ini sebagai pengganti.', 'Kesalahan yang sering muncul di Marketing & Penjualan: menjawab Ya karena pernah dilakukan sekali, atau menandai Tidak Berlaku untuk kondisi yang sebenarnya masih berlaku.', 'Jawaban Ya di Marketing & Penjualan berarti praktik ini sudah terlihat pada kerja minggu ini, bukan hanya ada di rencana.', 'Jawaban Tidak di Marketing & Penjualan menjadi urutan kerja. Bila butirnya tidak punya panduan untuk peserta, gunakan narasi seksi ini.', 'draft'),
  ('audit_2_3', 'C', 'Kas yang tumbuh tetap bisa mati. Yang diukur adalah batas kas, cadangan beberapa bulan, dan kemampuan membaca arus kas, bukan hanya omzet.', 'Seksi C Keuangan & Akuntansi ikut menentukan apakah transisi ini ditopang praktik harian, bukan hanya niat owner.', 'Kas yang tumbuh tetap bisa mati. Yang diukur adalah batas kas, cadangan beberapa bulan, dan kemampuan membaca arus kas, bukan hanya omzet. Butir bintang di seksi ini adalah gerbang. Skor butir biasa tidak menutup butir bintang yang dijawab Tidak.', 'Baca seksi Keuangan & Akuntansi dalam dua lapis. Butir yang dijawab Tidak Berlaku keluar dari pembilang dan penyebut. Butir tanpa panduan peserta memakai narasi seksi ini sebagai pengganti.', 'Kesalahan yang sering muncul di Keuangan & Akuntansi: menjawab Ya karena pernah dilakukan sekali, atau menandai Tidak Berlaku untuk kondisi yang sebenarnya masih berlaku.', 'Jawaban Ya di Keuangan & Akuntansi berarti praktik ini sudah terlihat pada kerja minggu ini, bukan hanya ada di rencana.', 'Jawaban Tidak di Keuangan & Akuntansi menjadi urutan kerja. Bila butirnya tidak punya panduan untuk peserta, gunakan narasi seksi ini.', 'draft'),
