INSERT INTO report_status_narratives (audit_code, status, headline, summary, implication, focus, review_status) VALUES
  ('audit_1_2', 'DALAM_BAHAYA', 'Ini krisis, bukan sekadar gerbang yang belum terbuka', 'Tiga atau lebih butir kunci di Cari Makan dijawab Tidak, dan skor butir biasa berada di bawah 50%. Krisis Kepemimpinan sedang terjadi di operasi, bukan hanya di judul fase.', 'Gerbang Fase 1: Krisis Kepemimpinan — belum terlewati. Status ini dibaca dari butir bintang dan skor butir non-kunci. Tidak Berlaku keluar dari pembilang dan penyebut.', 'Tutup butir kunci yang Tidak lebih dulu, lalu angkat seksi Cari Makan yang skor butir biasanya paling rendah.', 'draft'),
  ('audit_1_2', 'BELUM_SIAP', 'Gerbang kunci masih tertutup', 'Ada butir kunci yang dijawab Tidak pada transisi Cari Makan ke Cari Duit. Skor butir biasa, setinggi apa pun, tidak menggantikan gerbang itu.', 'Gerbang Fase 1: Krisis Kepemimpinan — belum terlewati. Status ini dibaca dari butir bintang dan skor butir non-kunci. Tidak Berlaku keluar dari pembilang dan penyebut.', 'Tutup butir kunci yang Tidak lebih dulu, lalu angkat seksi Cari Makan yang skor butir biasanya paling rendah.', 'draft'),
  ('audit_1_2', 'SIAP_NAIK', 'Gerbang sudah terbuka', 'Semua butir kunci yang dinilai dijawab Ya, dan skor butir biasa mencapai minimal 80% tanpa pembulatan. Krisis Kepemimpinan pada gerbang fase ini sudah terlewati.', 'Gerbang Fase 1: Krisis Kepemimpinan — sudah terlewati. Status ini dibaca dari butir bintang dan skor butir non-kunci. Tidak Berlaku keluar dari pembilang dan penyebut.', 'Jaga bukti butir kunci yang sudah Ya, dan bereskan seksi di bawah 50% sebelum fase berikutnya menekannya.', 'draft'),
  ('audit_1_2', 'HAMPIR', 'Kunci lulus, pondasi belum penuh', 'Semua butir kunci yang dinilai dijawab Ya, dan skor butir biasa berada di 60% sampai di bawah 80%. Jarak ke ambang 80% adalah pekerjaan butir biasa, bukan butir bintang.', 'Gerbang Fase 1: Krisis Kepemimpinan — belum terlewati. Status ini dibaca dari butir bintang dan skor butir non-kunci. Tidak Berlaku keluar dari pembilang dan penyebut.', 'Tutup butir kunci yang Tidak lebih dulu, lalu angkat seksi Cari Makan yang skor butir biasanya paling rendah.', 'draft'),
  ('audit_1_2', 'PERLU_FONDASI', 'Gerbang utama sudah terbuka, tapi pondasi pendukungnya belum terbangun.', 'Gerbang utama sudah terbuka, tapi pondasi pendukungnya belum terbangun. Semua butir kunci yang dinilai Ya, sementara skor butir biasa masih di bawah 60%.', 'Gerbang Fase 1: Krisis Kepemimpinan — belum terlewati. Status ini dibaca dari butir bintang dan skor butir non-kunci. Tidak Berlaku keluar dari pembilang dan penyebut.', 'Mulai dari kurikulum fondasi fase ini. Jangan loncat ke kanal atau orang baru sebelum praktik dasar jalan.', 'draft'),
  ('audit_1_2', 'TIDAK_DAPAT_DINILAI', 'Terlalu banyak jawaban Tidak Berlaku, jadi hasilnya tidak representatif.', 'Terlalu banyak jawaban Tidak Berlaku, jadi hasilnya tidak representatif. Angka pada laporan ini bukan dasar untuk belanja, rekrut, atau ekspansi.', 'Gerbang Fase 1: Krisis Kepemimpinan — belum terlewati. Status ini dibaca dari butir bintang dan skor butir non-kunci. Tidak Berlaku keluar dari pembilang dan penyebut.', 'Tandai ulang butir Tidak Berlaku. Yang memang di luar model bisnis tetap Tidak Berlaku. Yang belum dikerjakan dijawab Tidak, lalu audit diulang.', 'draft'),
  ('audit_2_3', 'DALAM_BAHAYA', 'Ini krisis, bukan sekadar gerbang yang belum terbuka', 'Tiga atau lebih butir kunci di Cari Duit dijawab Tidak, dan skor butir biasa berada di bawah 50%. Krisis Otonomi sedang terjadi di operasi, bukan hanya di judul fase.', 'Gerbang Fase 2: Krisis Otonomi — belum terlewati. Status ini dibaca dari butir bintang dan skor butir non-kunci. Tidak Berlaku keluar dari pembilang dan penyebut.', 'Tutup butir kunci yang Tidak lebih dulu, lalu angkat seksi Cari Duit yang skor butir biasanya paling rendah.', 'draft'),
  ('audit_2_3', 'BELUM_SIAP', 'Gerbang kunci masih tertutup', 'Ada butir kunci yang dijawab Tidak pada transisi Cari Duit ke Bangun Sistem. Skor butir biasa, setinggi apa pun, tidak menggantikan gerbang itu.', 'Gerbang Fase 2: Krisis Otonomi — belum terlewati. Status ini dibaca dari butir bintang dan skor butir non-kunci. Tidak Berlaku keluar dari pembilang dan penyebut.', 'Tutup butir kunci yang Tidak lebih dulu, lalu angkat seksi Cari Duit yang skor butir biasanya paling rendah.', 'draft'),
  ('audit_2_3', 'SIAP_NAIK', 'Gerbang sudah terbuka', 'Semua butir kunci yang dinilai dijawab Ya, dan skor butir biasa mencapai minimal 80% tanpa pembulatan. Krisis Otonomi pada gerbang fase ini sudah terlewati.', 'Gerbang Fase 2: Krisis Otonomi — sudah terlewati. Status ini dibaca dari butir bintang dan skor butir non-kunci. Tidak Berlaku keluar dari pembilang dan penyebut.', 'Jaga bukti butir kunci yang sudah Ya, dan bereskan seksi di bawah 50% sebelum fase berikutnya menekannya.', 'draft'),
  ('audit_2_3', 'HAMPIR', 'Kunci lulus, pondasi belum penuh', 'Semua butir kunci yang dinilai dijawab Ya, dan skor butir biasa berada di 60% sampai di bawah 80%. Jarak ke ambang 80% adalah pekerjaan butir biasa, bukan butir bintang.', 'Gerbang Fase 2: Krisis Otonomi — belum terlewati. Status ini dibaca dari butir bintang dan skor butir non-kunci. Tidak Berlaku keluar dari pembilang dan penyebut.', 'Tutup butir kunci yang Tidak lebih dulu, lalu angkat seksi Cari Duit yang skor butir biasanya paling rendah.', 'draft'),
  ('audit_2_3', 'PERLU_FONDASI', 'Gerbang utama sudah terbuka, tapi pondasi pendukungnya belum terbangun.', 'Gerbang utama sudah terbuka, tapi pondasi pendukungnya belum terbangun. Semua butir kunci yang dinilai Ya, sementara skor butir biasa masih di bawah 60%.', 'Gerbang Fase 2: Krisis Otonomi — belum terlewati. Status ini dibaca dari butir bintang dan skor butir non-kunci. Tidak Berlaku keluar dari pembilang dan penyebut.', 'Mulai dari kurikulum fondasi fase ini. Jangan loncat ke kanal atau orang baru sebelum praktik dasar jalan.', 'draft'),
  ('audit_2_3', 'TIDAK_DAPAT_DINILAI', 'Terlalu banyak jawaban Tidak Berlaku, jadi hasilnya tidak representatif.', 'Terlalu banyak jawaban Tidak Berlaku, jadi hasilnya tidak representatif. Angka pada laporan ini bukan dasar untuk belanja, rekrut, atau ekspansi.', 'Gerbang Fase 2: Krisis Otonomi — belum terlewati. Status ini dibaca dari butir bintang dan skor butir non-kunci. Tidak Berlaku keluar dari pembilang dan penyebut.', 'Tandai ulang butir Tidak Berlaku. Yang memang di luar model bisnis tetap Tidak Berlaku. Yang belum dikerjakan dijawab Tidak, lalu audit diulang.', 'draft'),
  ('audit_3_4', 'DALAM_BAHAYA', 'Ini krisis, bukan sekadar gerbang yang belum terbuka', 'Tiga atau lebih butir kunci di Bangun Sistem dijawab Tidak, dan skor butir biasa berada di bawah 50%. Krisis Kontrol sedang terjadi di operasi, bukan hanya di judul fase.', 'Gerbang Fase 3: Krisis Kontrol — belum terlewati. Status ini dibaca dari butir bintang dan skor butir non-kunci. Tidak Berlaku keluar dari pembilang dan penyebut.', 'Tutup butir kunci yang Tidak lebih dulu, lalu angkat seksi Bangun Sistem yang skor butir biasanya paling rendah.', 'draft'),
  ('audit_3_4', 'BELUM_SIAP', 'Gerbang kunci masih tertutup', 'Ada butir kunci yang dijawab Tidak pada transisi Bangun Sistem ke Cari Talent. Skor butir biasa, setinggi apa pun, tidak menggantikan gerbang itu.', 'Gerbang Fase 3: Krisis Kontrol — belum terlewati. Status ini dibaca dari butir bintang dan skor butir non-kunci. Tidak Berlaku keluar dari pembilang dan penyebut.', 'Tutup butir kunci yang Tidak lebih dulu, lalu angkat seksi Bangun Sistem yang skor butir biasanya paling rendah.', 'draft'),
