INSERT INTO phase_report_closings (audit_code, closing_text, next_phase_title, next_phase_preview, prepare_text, review_status) VALUES
  ('audit_1_2', 'Transisi Cari Makan ke Cari Duit selesai dibaca dari gerbang bintang dan skor butir biasa. Simpan bukti butir yang sudah Ya, dan jangan naik hanya karena sibuk.', 'Menuju Cari Duit', 'Fase Cari Duit menambah beban pada proses yang hari ini masih menempel di owner.', 'Siapkan satu bukti untuk setiap butir kunci yang sudah Ya, dan satu urutan kerja untuk seksi yang skornya paling rendah.', 'draft'),
  ('audit_2_3', 'Transisi Cari Duit ke Bangun Sistem selesai dibaca dari gerbang bintang dan skor butir biasa. Simpan bukti butir yang sudah Ya, dan jangan naik hanya karena sibuk.', 'Menuju Bangun Sistem', 'Fase Bangun Sistem menambah beban pada proses yang hari ini masih menempel di owner.', 'Siapkan satu bukti untuk setiap butir kunci yang sudah Ya, dan satu urutan kerja untuk seksi yang skornya paling rendah.', 'draft'),
  ('audit_3_4', 'Transisi Bangun Sistem ke Cari Talent selesai dibaca dari gerbang bintang dan skor butir biasa. Simpan bukti butir yang sudah Ya, dan jangan naik hanya karena sibuk.', 'Menuju Cari Talent', 'Fase Cari Talent menambah beban pada proses yang hari ini masih menempel di owner.', 'Siapkan satu bukti untuk setiap butir kunci yang sudah Ya, dan satu urutan kerja untuk seksi yang skornya paling rendah.', 'draft'),
  ('audit_4_5', 'Transisi Cari Talent ke Ekspansi selesai dibaca dari gerbang bintang dan skor butir biasa. Simpan bukti butir yang sudah Ya, dan jangan naik hanya karena sibuk.', 'Menuju Ekspansi', 'Fase ekspansi menggandakan cara kerja yang sudah tertulis. Tanpa playbook dan identitas, cabang baru hanya menyalin kekacauan.', 'Siapkan satu bukti untuk setiap butir kunci yang sudah Ya, dan satu urutan kerja untuk seksi yang skornya paling rendah.', 'draft')
ON CONFLICT (audit_code) DO UPDATE SET closing_text = EXCLUDED.closing_text, next_phase_title = EXCLUDED.next_phase_title, next_phase_preview = EXCLUDED.next_phase_preview, prepare_text = EXCLUDED.prepare_text, review_status = EXCLUDED.review_status, updated_at = NOW();

INSERT INTO recommendation_triggers (question_id, recommendation_id, trigger_on_answer, priority, is_active)
SELECT tq.id, rl.id, 'TIDAK', 6, true
FROM test_questions tq
JOIN audit_transitions a ON a.id = tq.audit_transition_id
JOIN test_sections ts ON ts.id = tq.section_id
JOIN recommendation_library rl ON rl.code = CASE a.code || '|' || ts.code
    WHEN 'audit_1_2|A' THEN 'rec-operasi-dasar'
    WHEN 'audit_1_2|B' THEN 'rec-penjualan-dasar'
    WHEN 'audit_1_2|C' THEN 'rec-laba-rugi'
    WHEN 'audit_1_2|D' THEN 'rec-pajak-rezim'
    WHEN 'audit_1_2|E' THEN 'rec-sdm-dasar'
    WHEN 'audit_1_2|F' THEN 'rec-kepemimpinan-awal'
    WHEN 'audit_1_2|G' THEN 'rec-budaya'
    WHEN 'audit_1_2|H' THEN 'rec-amanah'
    WHEN 'audit_2_3|A' THEN 'rec-operasi-dasar'
    WHEN 'audit_2_3|B' THEN 'rec-unit-economics'
    WHEN 'audit_2_3|C' THEN 'rec-kas-cadangan'
    WHEN 'audit_2_3|D' THEN 'rec-hubungan-kerja'
    WHEN 'audit_2_3|E' THEN 'rec-sdm-dasar'
    WHEN 'audit_2_3|F' THEN 'rec-sop'
    WHEN 'audit_2_3|G' THEN 'rec-integrasi-sistem'
    WHEN 'audit_2_3|H' THEN 'rec-budaya'
    WHEN 'audit_2_3|I' THEN 'rec-kader'
    WHEN 'audit_3_4|A' THEN 'rec-sistem-matang'
    WHEN 'audit_3_4|B' THEN 'rec-mesin-penjualan'
    WHEN 'audit_3_4|C' THEN 'rec-dashboard-kas'
    WHEN 'audit_3_4|D' THEN 'rec-coretax'
    WHEN 'audit_3_4|E' THEN 'rec-kader'
    WHEN 'audit_3_4|F' THEN 'rec-tata-kelola'
    WHEN 'audit_3_4|G' THEN 'rec-integrasi-sistem'
    WHEN 'audit_3_4|H' THEN 'rec-kader'
    WHEN 'audit_3_4|I' THEN 'rec-budaya'
    WHEN 'audit_3_4|J' THEN 'rec-amanah'
    WHEN 'audit_4_5|A' THEN 'rec-lean-birokrasi'
    WHEN 'audit_4_5|B' THEN 'rec-playbook-ekspansi'
    WHEN 'audit_4_5|C' THEN 'rec-modal-ekspansi'
    WHEN 'audit_4_5|D' THEN 'rec-uji-tuntas'
    WHEN 'audit_4_5|E' THEN 'rec-kader'
    WHEN 'audit_4_5|F' THEN 'rec-playbook-ekspansi'
    WHEN 'audit_4_5|G' THEN 'rec-identitas'
    WHEN 'audit_4_5|H' THEN 'rec-integrasi-sistem'
    WHEN 'audit_4_5|I' THEN 'rec-amanah'
    ELSE NULL END
WHERE rl.id IS NOT NULL
ON CONFLICT (question_id, recommendation_id, trigger_on_answer) DO UPDATE SET priority = EXCLUDED.priority, is_active = true;

INSERT INTO recommendation_triggers (question_id, recommendation_id, trigger_on_answer, priority, is_active)
SELECT tq.id, rl.id, 'TIDAK', 1, true
FROM (VALUES ('audit_1_2', 3, 'rec-pisah-uang'), ('audit_1_2', 14, 'rec-hpp'), ('audit_1_2', 30, 'rec-bep'), ('audit_1_2', 42, 'rec-pisah-uang'), ('audit_1_2', 43, 'rec-pisah-uang'), ('audit_1_2', 44, 'rec-laba-rugi'), ('audit_1_2', 47, 'rec-pajak-rezim'), ('audit_1_2', 81, 'rec-delegasi'), ('audit_2_3', 18, 'rec-unit-economics'), ('audit_2_3', 55, 'rec-kas-cadangan'), ('audit_2_3', 90, 'rec-sop'), ('audit_3_4', 12, 'rec-dashboard-kas'), ('audit_3_4', 48, 'rec-integrasi-sistem'), ('audit_4_5', 1, 'rec-lean-birokrasi'), ('audit_4_5', 8, 'rec-playbook-ekspansi'), ('audit_4_5', 12, 'rec-modal-ekspansi'), ('audit_4_5', 35, 'rec-identitas')) AS map(audit_code, question_number, rec_code)
JOIN audit_transitions a ON a.code = map.audit_code
JOIN test_questions tq ON tq.audit_transition_id = a.id AND tq.question_number = map.question_number
JOIN recommendation_library rl ON rl.code = map.rec_code
ON CONFLICT (question_id, recommendation_id, trigger_on_answer) DO UPDATE SET priority = EXCLUDED.priority, is_active = true;

