INSERT INTO upsell_items (product_id, name, short_desc, type, price, cta_label, cta_url, trigger_condition, is_active, sort_order, code) VALUES
  (NULL, 'Kelas & ebook fondasi Survival ke Cari Duit', 'Kurikulum pondasi untuk owner yang gerbang kuncinya sudah Ya, tetapi praktik sehari-hari masih di bawah 60%: memisahkan uang, menghitung HPP dan titik impas, membaca laba rugi bulanan, dan menunjuk orang pertama yang benar-benar membantu.', 'CURRICULUM', 0, 'Lihat kurikulum', '/akun/layanan#fondasi-audit-1-2', 'status:PERLU_FONDASI;audit:audit_1_2', true, 1, 'fondasi-audit-1-2'),
  (NULL, 'Kelas & ebook fondasi Cari Duit ke Bangun Sistem', 'Kurikulum pondasi saat delegasi belum menjadi sistem: margin per produk, kas minimal plus cadangan tiga bulan, SOP satu proses inti, dan perjanjian kerja yang membuat orang bisa bekerja tanpa owner menunggui.', 'CURRICULUM', 0, 'Lihat kurikulum', '/akun/layanan#fondasi-audit-2-3', 'status:PERLU_FONDASI;audit:audit_2_3', true, 2, 'fondasi-audit-2-3'),
  (NULL, 'Kelas & ebook fondasi Bangun Sistem ke Cari Talent', 'Kurikulum pondasi sebelum mencari talent: dashboard kas yang melihat ke depan, mesin penjualan yang tidak bergantung pada satu figur, KPI yang dipakai untuk keputusan, dan satu calon untuk setiap posisi kunci.', 'CURRICULUM', 0, 'Lihat kurikulum', '/akun/layanan#fondasi-audit-3-4', 'status:PERLU_FONDASI;audit:audit_3_4', true, 3, 'fondasi-audit-3-4'),
  (NULL, 'Kelas & ebook fondasi Cari Talent ke Ekspansi', 'Kurikulum pondasi sebelum melompat: memangkas lapisan persetujuan, menulis playbook yang bisa ditiru unit lain, menguji ketahanan kas, dan menuliskan identitas yang tidak boleh luntur saat bisnis digandakan.', 'CURRICULUM', 0, 'Lihat kurikulum', '/akun/layanan#fondasi-audit-4-5', 'status:PERLU_FONDASI;audit:audit_4_5', true, 4, 'fondasi-audit-4-5')
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, short_desc = EXCLUDED.short_desc, type = EXCLUDED.type, price = EXCLUDED.price, cta_label = EXCLUDED.cta_label, cta_url = EXCLUDED.cta_url, trigger_condition = EXCLUDED.trigger_condition, is_active = true, sort_order = EXCLUDED.sort_order;

INSERT INTO upsell_items (product_id, name, short_desc, type, price, cta_label, cta_url, trigger_condition, is_active, sort_order, code)
SELECT p.id, 'Coaching 1:1', 'Sesi pendampingan pada produk audit-coaching yang sudah ada. Harga mengikuti produk, tidak dibuat di laporan.', 'COACHING', p.price, 'Checkout coaching', '/checkout?product=audit-coaching', 'status:PERLU_FONDASI,BELUM_SIAP,DALAM_BAHAYA', true, 20, 'upsell-coaching-1-1'
FROM products p WHERE p.code = 'audit-coaching'
ON CONFLICT (code) DO UPDATE SET product_id = EXCLUDED.product_id, name = EXCLUDED.name, short_desc = EXCLUDED.short_desc, price = EXCLUDED.price, cta_label = EXCLUDED.cta_label, cta_url = EXCLUDED.cta_url, trigger_condition = EXCLUDED.trigger_condition, is_active = true;

UPDATE test_questions tq
SET guidance_audience = CASE
  WHEN btrim(COALESCE(tq.guidance_text, '')) IN ('', '-') THEN 'missing'
  WHEN tq.guidance_text ~* 'slide anda|materi anda|materi \(sirah\)|sirah anda|catatan asli|versi lama berbunyi|ringkasan dari|koreksi:|konsolidasi dengan|relevan langsung|pt anda|restrukturisasi anda|rencana restrukturisasi' THEN 'editor'
  ELSE 'customer' END
FROM audit_transitions a
WHERE tq.audit_transition_id = a.id AND a.code IN ('audit_1_2','audit_2_3','audit_3_4','audit_4_5');

UPDATE test_questions tq SET guidance_audience = 'editor'
FROM audit_transitions a, (VALUES ('audit_1_2', 43), ('audit_1_2', 52), ('audit_1_2', 77), ('audit_1_2', 82), ('audit_1_2', 83), ('audit_2_3', 8), ('audit_2_3', 76), ('audit_2_3', 77), ('audit_2_3', 79), ('audit_2_3', 80), ('audit_2_3', 87), ('audit_2_3', 90), ('audit_2_3', 150), ('audit_2_3', 153), ('audit_3_4', 26), ('audit_3_4', 28), ('audit_3_4', 46), ('audit_3_4', 55), ('audit_3_4', 60), ('audit_3_4', 63), ('audit_4_5', 9), ('audit_4_5', 23), ('audit_4_5', 26), ('audit_4_5', 28), ('audit_4_5', 35), ('audit_4_5', 39), ('audit_4_5', 43), ('audit_4_5', 46)) AS v(code, question_number)
WHERE tq.audit_transition_id = a.id AND a.code = v.code AND tq.question_number = v.question_number;

INSERT INTO site_settings (key, value) VALUES ('support_whatsapp', '') ON CONFLICT (key) DO NOTHING;

